 12	package com.sun.fortress.runtimeSystem;
 13	
 14	import java.util.concurrent.ForkJoinPool;
 15	import java.util.concurrent.ForkJoinTask;
 16	import java.util.concurrent.RecursiveAction;
 17	
 18	import java.util.Random;
 19	import java.util.concurrent.atomic.AtomicInteger;
 20	
 21	import static com.sun.fortress.runtimeSystem.FortressExecutable.numThreads;
 22	import static com.sun.fortress.runtimeSystem.FortressExecutable.spawnThreshold;
 23	
 24	import com.sun.fortress.useful.MagicNumbers;
 25	
 26	/** Base class for Fortress tasks.  Includes administrative methods
 27	 *  that make code generation for task spawn a bit easier.
 28	 *
 29	 *  We shy away from the "easiest thing of all": forking in the constructor.
 30	 *  Given the plethora of final fields in the usual Fortress task, such a step
 31	 *  would be a memory model disaster!  Instead, we generate code like:
 32	 *    Fib$task0 tmp = new Fib$task0(arg);
 33	 *    tmp.forkIfProfitable();
 34	 *    ... other code ...
 35	 *    tmp.joinOrRun();
 36	 *    ... use tmp.result (compiler-inserted field) if desired ...
 37	 */
 38	public abstract class BaseTask extends FortressExecutable {
 39	    // Could get this by hacking ForkJoinTask's status field, but
 40	    // not touching that for now as it's too changeable
 41	    private static final int UNFORKED = 0;
 42	    private static final int FORKED = 1;
 43	    private static final int EXECUTED = 2;
 44	    private int actuallyForked = UNFORKED;
 45	
 46	    BaseTask parent;
 47	    Transaction transaction;
 48	    private static Random gen = new Random();
 49	
 50	    private static Boolean debug = false;
 51	
 52	    private static void debug(String s) {
 53	        if (debug)
 54	            System.out.println("BaseTaskDebug: " + Thread.currentThread().getName() + ":" + s);
 55	    }
 56	
 57	    /** Each base task has a depth in the pedigree tree, the value of
 58	    the next magic number, a unique gamma value that is the dot
 59	    product of the task's pedigree and the magic numbers array, and a
 60	    dot product that is the task's gamma value with extra magic added
 61	    in for each random number the task generates **/
 62	
 63	    private int depth;
 64	    private long nextMagicNumber; 
 65	    private long gamma; 
 66	    private long dotProduct;
 67	    
 68	    // The constructor used by the primordial task.
 69	    public BaseTask() {
 70	        super();
 71	        this.parent = null;
 72	        this.transaction = null;
 73	
 74	        // Pedigree information
 75	        this.depth = 0;
 76	        this.nextMagicNumber = 
 77	            MagicNumbers.trulyRandomLongNumbers(this.depth + 1);
 78	        this.gamma = 
 79	            MagicNumbers.trulyRandomLongNumbers(this.depth);
 80	        this.dotProduct = this.gamma;
 81	    }
 82	
 83	    public BaseTask(BaseTask parent) {
 84	        super();
 85	        this.parent = parent;
 86	        this.transaction = parent.transaction;
 87	
 88	        // Pedigree information
 89	        this.depth = parent.getDepth() + 1;
 90	        this.nextMagicNumber = 
 91	            MagicNumbers.trulyRandomLongNumbers(this.depth + 1);
 92	        this.gamma = parent.makeNewChild();
 93	        this.dotProduct = this.gamma;
 94	    }
 95	
 96	    private int getDepth() {
 97	        return this.depth;
 98	    }
 99	
100	    /* Returns a unique gamma for a child task */
101	    public long makeNewChild() {
102	        this.gamma += this.nextMagicNumber;
103	        return this.gamma;
104	    }
105	
106	    /* Records that a new random number has been asked for, and
107	     * returns the task's dotProduct */
108	    public long makeNewRandom() {
109	        this.dotProduct += this.nextMagicNumber;
110	        return dotProduct;
111	    }
112	
113	    /* For a group of arms that completes abruptly: waits for this arm
114	     * where it was forked, and takes what it threw.  An arm that was never
115	     * forked is not run.  The current task is saved and restored around the
116	     * join, as joinOrRun does. */
117	    public final void joinIfForked() {
118	        if (actuallyForked == UNFORKED) return;
119	        Thread thread = Thread.currentThread();
120	        if (thread instanceof FortressTaskRunner) {
121	            FortressTaskRunner ftr = (FortressTaskRunner) thread;
122	            BaseTask saved = ftr.task();
123	            try {
124	                this.quietlyJoin();
125	            } finally {
126	                ftr.setTask(saved);
127	            }
128	        } else {
129	            this.quietlyJoin();
130	        }
131	    }
132	
133	    private static boolean unsafeWorthSpawning() {
134	        return (numThreads > 1 &&
135	                (spawnThreshold < 0 || getSurplusQueuedTaskCount() <= spawnThreshold));
136	    }
137	
138	    public static boolean worthSpawning() {
139	        return numThreads > 1 && !ForkJoinTask.inForkJoinPool() || unsafeWorthSpawning();
140	    }
141	
142	    // Corner case: we attempted to spawn work from a class
143	    // initializer.  That doesn't work as the initializer isn't run in
144	    // a ForkJoinWorkerThread.  So we must submit the task to the
145	    // global task pool instead.
146	    private final void executeAlways() {
147	        FortressExecutable.group.execute(this);
148	        actuallyForked = EXECUTED;
149	    }
150	
151	    private final void forkAlways() {
152	        this.fork();
153	        actuallyForked = FORKED;
154	    }
155	
156	    public final void forkIfProfitable() {
157	        if (ForkJoinTask.inForkJoinPool()) {
158	            if (unsafeWorthSpawning()) {
159	                this.forkAlways();
160	            }
161	        } else {
162	            this.executeAlways();
163	        }
164	    }
165	
166	    public final void joinOrRun() {
167	        // Emphasize common UNFORKED case.
168	        if (actuallyForked == UNFORKED) {
169	            this.compute();
170	        } else {
171	            // java.util.concurrent has no helpJoin(); its join() already
172	            // helps by running queued subtasks when called from a worker
173	            // thread, so FORTRESS_HELP_JOIN (useHelpJoin) is now a no-op.
174	            //
175	            // That helping breaks an invariant jsr166y's blocking join
176	            // preserved: generated compute() bodies point the worker's
177	            // current-task field at themselves (BaseTask.setTask) and never
178	            // restore it, and the transaction statics below resolve the
179	            // current transaction through that field.  A task run on this
180	            // thread while join() helps leaves the field pointing at an
181	            // unrelated task, corrupting transaction state in the joiner's
182	            // continuation.  Save and restore the field across join(),
183	            // mirroring Evaluator's setCurrentTask(currentTask) after
184	            // TupleTask.invokeAll on the interpreter side.
185	            Thread thread = Thread.currentThread();
186	            if (thread instanceof FortressTaskRunner) {
187	                FortressTaskRunner ftr = (FortressTaskRunner) thread;
188	                BaseTask saved = ftr.task();
189	                try {
190	                    this.join();
191	                } finally {
192	                    ftr.setTask(saved);
193	                }
194	            } else {
195	                this.join();
196	            }
197	        }
198	    }
199	
200	   public static void startTransaction() {
201	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
202	        BaseTask currentTask = ftr.getTask();
203	        if (debug) debug("startTransaction: ftr = " + ftr + " current task = " + currentTask);
204	
205	        Transaction transaction = Transaction.TXBegin(currentTask.transaction());
206	        if (debug) debug("Start transaction ftr = " + ftr + " current action = " + currentTask + " trans = " + transaction);
207	        currentTask.setTransaction(transaction);
208	    }
209	
210	    public static void endTransaction() {
211	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
212	        BaseTask currentTask = ftr.getTask();
213	        if (debug) debug("endTransaction: ftr = " + ftr + " current task = " + currentTask);
214	        Transaction transaction = ftr.getTask().transaction();
215	        if (debug) debug("End transaction ftr = " + ftr + " current action = " + currentTask + " trans = " + transaction);
216	        if (transaction != null) {
217	            transaction.TXCommit();
218	            currentTask.setTransaction(transaction.getParent());
219	        }
220	        ftr.recordEndTransaction();
221	    }
222	    
223	    public static void delayTransaction() {
224	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
225	        long startTime = System.nanoTime();
226	        long elapsedTime = System.nanoTime() - startTime;
227	
228	        if (useExponentialBackoff) {
229	            double r = gen.nextDouble() + 0.5; // Random number between 0.5 and 1.5
230	            long waitNanoseconds = (long) ((1L << (ftr.getRetries() + machineConstant)) * r);
231	            
232	            while (elapsedTime < waitNanoseconds) {
233	                elapsedTime = System.nanoTime() - startTime;
234	            }
235	        }
236	        
237	        ftr.incElapsedTime(elapsedTime);
238	        ftr.incRetries();
239	    }
240	
241	    public static Transaction getCurrentTransaction() {
242	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
243	        if (debug) debug("getCurrentTransaction: ftr = " + ftr );
244	        if (ftr.getTask() != null)
245	            return ftr.getTask().transaction();
246	        else return null;
247	    }
248	
249	    public static BaseTask getCurrentTask() {
250	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
251	        if (debug) debug("getCurrentTask: ftr = " + ftr );
252	        return ftr.getTask();
253	    }
254	
255	    public static boolean inATransaction() {
256	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
257	        if (debug) debug("inATransaction: ftr = " + ftr + " task = " + ftr.getTask());
258	
259	        if (ftr.getTask() != null) 
260	            if (ftr.getTask().transaction() != null)
261	                return true;
262	        return false;
263	    }
264	
265	    public static void setTask(BaseTask t) {
266	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
267	        if (debug) debug("setTask: ftr = " + ftr + " task = " + t);
268	        ftr.setTask(t);
269	    }
270	
271	    Transaction transaction() {
272	        return transaction;
273	    }
274	
275	    public void setTransaction(Transaction t) {
276	        transaction = t;
277	    }    
278	
279	    public void printStatistics() {
280	        FortressTaskRunnerGroup ftrg = (FortressTaskRunnerGroup) getPool();
281	        ftrg.printStatistics();
282	    }
283	
284	    /**
285	     * The handler of a compiled atomic block, with whatever its body or its commit threw.  It ends
286	     * the block's transaction, whose writes go with it.  It returns for an abort of that transaction,
287	     * and the block starts again: an abort that names it, the abort() of a program, which names none
288	     * and is taken by the innermost block, or any abort that reaches the outermost block.  It throws
289	     * on an abort that names an ancestor, whose block starts again, and any other exception, which
290	     * leaves the block; a nested transaction first hands the reads on which that exception was thrown
291	     * to its parent (Transaction.TXLeave).
292	     */
293	    public static void leaveTransaction(Throwable t) {
294	        FortressTaskRunner ftr = (FortressTaskRunner) Thread.currentThread();
295	        BaseTask currentTask = ftr.getTask();
296	        Transaction transaction = currentTask.transaction();
297	        if (debug) debug("Leave transaction ftr = " + ftr + " current action = " + currentTask + " trans = " + transaction + " on " + t);
298	        if (transaction == null)
299	            BaseTask.<RuntimeException>throwOn(t);
300	        currentTask.setTransaction(transaction.getParent());
301	        if (!(t instanceof TransactionAbortException)) {
302	            try {
303	                transaction.TXLeave();
304	            } catch (TransactionAbortException stale) {
305	                t = stale;
306	            }
307	        }
308	        if (t instanceof TransactionAbortException) {
309	            Transaction named = ((TransactionAbortException) t).transaction();
310	            if (named == null || named == transaction || transaction.getParent() == null)
311	                return;
312	        }
313	        BaseTask.<RuntimeException>throwOn(t);
314	    }
315	
316	    /** Throws t as it is, checked or not, as generated code throws. */
317	    @SuppressWarnings("unchecked")
318	    private static <T extends Throwable> void throwOn(Throwable t) throws T {
319	        throw (T) t;
320	    }
321	}

